"use client";

import { animate, motion, useMotionValue, useReducedMotion, useTransform, type Transition } from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for a time scrubber. Times are minutes after midnight. Pass `value` to control it, or `defaultValue` to let it hold its own time. */
export interface TimeScrubberProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (minutes: number) => void;
  /** The earliest time on the ruler. Defaults to midnight. */
  min?: number;
  /** The latest time on the ruler. Defaults to the next midnight, 1440. */
  max?: number;
  /** The minutes between two ticks. The ruler always comes to rest on a tick. Defaults to 15. */
  step?: number;
  /** Names the scrubber for screen readers and shows as its visible label. */
  label: string;
  /** Formats the time shown above the ruler and read out as `aria-valuetext`. Defaults to "9:45 AM". */
  formatValue?: (minutes: number) => string;
  disabled?: boolean;
  className?: string;
}

type Phase = "idle" | "held" | "dragging" | "coasting";

// Damping 53 is 2 × √700, rounded up: critically damped, so the ruler lands on a tick without wobble.
const SNAP: Transition = { type: "spring", stiffness: 700, damping: 53, mass: 1 };
// A fling loses speed by a factor of e every 325 ms, close to how a phone list coasts.
const FRICTION_MS = 325;
// CSS pixels per millisecond. The cap keeps the hardest fling to a coast of about 1,300 pixels.
const MAX_SPEED = 4;
const REST_SPEED = 0.02;
// Only the last 100 ms of the drag count toward the release speed.
const SAMPLE_WINDOW_MS = 100;
// A press that moves less than this many CSS pixels is a tap, not a drag.
const SLOP = 4;
// The gap between two ticks, in rem.
const TICK_GAP_REM = 0.75;
const PAGE_MINUTES = 60;

const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value));

// The decimal places in a number, such as 1 for 0.1 and 7 for 1e-7.
const placesOf = (number: number) => {
  const [digits, exponent = "0"] = String(number).split("e");
  return clamp((digits.split(".")[1]?.length ?? 0) - Number(exponent), 0, 100);
};
// A count within float error of a whole number is that whole number, so 0.3 / 0.1 counts as 3 ticks.
const wholeIfClose = (count: number) => (Math.abs(count - Math.round(count)) < 1e-9 ? Math.round(count) : count);

const formatClock = (minutes: number) => {
  const whole = ((Math.round(minutes) % 1440) + 1440) % 1440;
  const hours = Math.floor(whole / 60);
  const mins = whole % 60;
  const hour = hours % 12 === 0 ? 12 : hours % 12;
  return `${hour}:${String(mins).padStart(2, "0")} ${hours < 12 ? "AM" : "PM"}`;
};

const formatHour = (minutes: number) => {
  const hours = Math.floor((((minutes % 1440) + 1440) % 1440) / 60);
  const hour = hours % 12 === 0 ? 12 : hours % 12;
  return `${hour} ${hours < 12 ? "AM" : "PM"}`;
};

/**
 * Sets a time by dragging a ruler of ticks under a fixed marker. A fling keeps
 * the ruler moving until friction stops it, then it settles on the nearest
 * tick. The arrow keys move one tick, Page Up and Page Down move an hour.
 */
export function TimeScrubber({
  value,
  defaultValue,
  onValueChange,
  min = 0,
  max = 1440,
  step = 15,
  label,
  formatValue = formatClock,
  disabled,
  className,
}: TimeScrubberProps) {
  // The selectable range ends at `max`, even when the range is shorter than one step or not a whole number of steps.
  const top = Math.max(max, min);
  const span = top - min;
  // The ruler rests on a tick, or on `max` when that is nearer, so both ends stay reachable.
  // A fractional step leaves float error, so 3 × 0.1 reads 0.30000000000000004. Rounding to the grid's places removes it.
  const places = Math.max(placesOf(min), placesOf(step));
  const tickAt = (ticks: number) => Number((min + ticks * step).toFixed(places));
  const snap = (minutes: number) => {
    const inside = clamp(minutes, min, top);
    const onTick = Math.min(tickAt(Math.round(wholeIfClose((inside - min) / step))), top);
    return top - inside < Math.abs(onTick - inside) ? top : onTick;
  };
  // Moves a number of steps from a time that may sit between ticks, such as a `max` off the grid: the first step lands on a tick.
  const stepFrom = (from: number, steps: number) => {
    const ticksIn = wholeIfClose((from - min) / step);
    return tickAt((steps > 0 ? Math.floor(ticksIn) : Math.ceil(ticksIn)) + steps);
  };
  const shareOf = (minutes: number) => (span > 0 ? (minutes - min) / span : 0);
  const [ownValue, setOwnValue] = useState(() => snap(defaultValue ?? min));
  const [phase, setPhase] = useState<Phase>("idle");
  const current = snap(value ?? ownValue);
  const reduceMotion = useReducedMotion();
  const labelId = useId();

  // The time under the marker changes on every frame of a drag, so it lives
  // in a motion value and reaches the page without a React render.
  const position = useMotionValue(current);
  // The ruler starts at the marker and slides left by the share of the day that has passed.
  const rulerX = useTransform(position, (minutes) => `${-shareOf(minutes) * 100}%`);

  const rulerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const gesture = useRef<{
    pointerId: number;
    startX: number;
    startMinutes: number;
    minutesPerPixel: number;
    dragging: boolean;
    samples: { time: number; x: number }[];
  } | null>(null);
  const coastFrame = useRef(0);
  const emitted = useRef(current);
  useLayoutEffect(() => {
    emitted.current = current;
  }, [current]);
  useEffect(() => () => cancelAnimationFrame(coastFrame.current), []);

  // Turning `disabled` on drops the gesture and stops a coast where it is.
  if (disabled && phase !== "idle") setPhase("idle");
  useLayoutEffect(() => {
    if (!disabled) return;
    cancelAnimationFrame(coastFrame.current);
    gesture.current = null;
  }, [disabled]);

  // A new range or step drops the gesture the same way: its frames would keep sending times on the old ruler.
  // The ruler then settles onto the new one.
  const grid = `${min}/${top}/${step}`;
  const [gestureGrid, setGestureGrid] = useState(grid);
  if (gestureGrid !== grid) {
    setGestureGrid(grid);
    if (phase !== "idle") setPhase("idle");
  }
  useLayoutEffect(() => {
    cancelAnimationFrame(coastFrame.current);
    gesture.current = null;
  }, [min, top, step]);

  // Outside a gesture the ruler springs to the value: a key press, a new `value`, or the tick nearest where a coast stopped.
  useEffect(() => {
    if (phase !== "idle" || position.get() === current) return;
    if (reduceMotion) {
      position.set(current);
      return;
    }
    const settle = animate(position, current, SNAP);
    return () => settle.stop();
  }, [phase, current, reduceMotion, position]);

  const emit = (next: number) => {
    emitted.current = next;
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  // A drag or a coast sends each new time once, even while a controlled `value` lags behind it.
  const follow = (minutes: number) => {
    position.set(minutes);
    const next = snap(minutes);
    if (next !== emitted.current) emit(next);
  };

  // A key press asks again from the time shown, so it repeats even when the parent keeps `value` where it was.
  const choose = (minutes: number) => {
    const next = snap(minutes);
    if (next !== current) emit(next);
  };

  // Friction slows the coast. It stops at either end of the ruler and never passes it.
  const coast = (pixelSpeed: number, minutesPerPixel: number) => {
    let speed = -clamp(pixelSpeed, -MAX_SPEED, MAX_SPEED) * minutesPerPixel;
    const restSpeed = REST_SPEED * minutesPerPixel;
    let last = performance.now();
    const tick = () => {
      const now = performance.now();
      const decay = Math.exp(-(now - last) / FRICTION_MS);
      last = now;
      const target = position.get() + speed * FRICTION_MS * (1 - decay);
      const next = clamp(target, min, top);
      speed *= decay;
      follow(next);
      if (next !== target || Math.abs(speed) < restSpeed) {
        setPhase("idle");
        return;
      }
      coastFrame.current = requestAnimationFrame(tick);
    };
    coastFrame.current = requestAnimationFrame(tick);
  };

  const minutesAt = (clientX: number) => {
    const held = gesture.current;
    if (!held) return position.get();
    // Dragging the ruler right brings earlier times under the marker.
    return clamp(held.startMinutes - (clientX - held.startX) * held.minutesPerPixel, min, top);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled || gesture.current || event.button !== 0) return;
    cancelAnimationFrame(coastFrame.current);
    emitted.current = current;
    const rulerWidth = rulerRef.current?.getBoundingClientRect().width ?? 0;
    gesture.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startMinutes: position.get(),
      minutesPerPixel: rulerWidth > 0 ? span / rulerWidth : 0,
      dragging: false,
      samples: [{ time: performance.now(), x: event.clientX }],
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
    inputRef.current?.focus({ preventScroll: true });
    setPhase("held");
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const held = gesture.current;
    if (!held || event.pointerId !== held.pointerId) return;
    if (!held.dragging) {
      if (Math.abs(event.clientX - held.startX) < SLOP) return;
      held.dragging = true;
      setPhase("dragging");
    }
    const now = performance.now();
    held.samples = [...held.samples.filter((sample) => now - sample.time <= SAMPLE_WINDOW_MS), { time: now, x: event.clientX }];
    follow(minutesAt(event.clientX));
  };

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const held = gesture.current;
    if (!held || event.pointerId !== held.pointerId) return;
    gesture.current = null;
    const now = performance.now();
    // The release point counts too, so a drag that stopped before the finger lifted does not coast.
    const recent = [...held.samples.filter((sample) => now - sample.time <= SAMPLE_WINDOW_MS), { time: now, x: event.clientX }];
    const first = recent[0];
    const last = recent[recent.length - 1];
    const elapsed = first && last ? last.time - first.time : 0;
    const speed = held.dragging && first && last && elapsed > 0 ? (last.x - first.x) / elapsed : 0;
    if (reduceMotion || Math.abs(speed) < REST_SPEED || held.minutesPerPixel === 0) {
      setPhase("idle");
      return;
    }
    setPhase("coasting");
    coast(speed, held.minutesPerPixel);
  };

  // The browser took the pointer, for example to scroll the page. The ruler settles on the nearest tick.
  const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerId !== gesture.current?.pointerId) return;
    gesture.current = null;
    setPhase("idle");
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const pageSteps = Math.max(Math.round(PAGE_MINUTES / step), 1);
    const moves = new Map([
      ["ArrowLeft", stepFrom(current, -1)],
      ["ArrowDown", stepFrom(current, -1)],
      ["ArrowRight", stepFrom(current, 1)],
      ["ArrowUp", stepFrom(current, 1)],
      ["PageDown", stepFrom(current, -pageSteps)],
      ["PageUp", stepFrom(current, pageSteps)],
      ["Home", min],
      ["End", top],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    cancelAnimationFrame(coastFrame.current);
    setPhase("idle");
    choose(next);
  };

  // Ticks stop at the last one inside the range; the ruler itself runs on to `max`.
  const ticks = Math.floor(span / step);
  const text = formatValue(current);

  return (
    <div className={cn("flex w-full flex-col gap-2", disabled && "opacity-50", className)}>
      <div className="flex items-baseline justify-between gap-4 text-sm">
        <span id={labelId} className="font-medium text-foreground">
          {label}
        </span>
        <span aria-hidden="true" className="shrink-0 text-lg font-semibold whitespace-nowrap text-foreground tabular-nums">
          {text}
        </span>
      </div>
      <div
        data-phase={phase}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerCancel}
        className={cn(
          "relative h-16 w-full touch-pan-y overflow-hidden rounded-xl border border-border bg-card select-none",
          disabled ? "cursor-not-allowed" : "cursor-grab data-[phase=dragging]:cursor-grabbing",
        )}
      >
        <motion.div
          ref={rulerRef}
          aria-hidden="true"
          style={{ x: rulerX, width: `${(span / step) * TICK_GAP_REM}rem` }}
          className="pointer-events-none absolute inset-y-0 left-1/2"
        >
          {Array.from({ length: ticks + 1 }, (_, index) => {
            const minutes = min + index * step;
            const hour = minutes % 60 === 0;
            const half = minutes % 30 === 0;
            return (
              <span
                key={minutes}
                style={{ left: `${shareOf(minutes) * 100}%` }}
                className="absolute top-0 flex -translate-x-1/2 flex-col items-center"
              >
                <span
                  className={cn(
                    "w-px rounded-full",
                    hour ? "h-5 bg-foreground/70" : half ? "h-3.5 bg-muted-foreground/60" : "h-2.5 bg-muted-foreground/40",
                  )}
                />
                {hour ? (
                  <span className="mt-1.5 text-xs whitespace-nowrap text-muted-foreground tabular-nums">{formatHour(minutes)}</span>
                ) : null}
              </span>
            );
          })}
        </motion.div>
        {/* Both edges fade into the card, so ticks leave the frame softly. */}
        <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 left-0 w-12 bg-linear-to-r from-card to-transparent" />
        <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 right-0 w-12 bg-linear-to-l from-card to-transparent" />
        <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 left-1/2 w-0.5 -translate-x-1/2 rounded-full bg-primary" />
        {/* A native range input gives the slider role, the value and the focus. The ruler owns the pointer. */}
        <input
          ref={inputRef}
          type="range"
          min={min}
          max={top}
          // A range that is not a whole number of steps would make the browser round `max` down, so the input then takes any value.
          step={span % step === 0 ? step : "any"}
          value={current}
          disabled={disabled}
          aria-labelledby={labelId}
          aria-valuetext={text}
          // A screen reader's increment may land between ticks, so it moves one whole step in that direction.
          onChange={(event) => {
            const asked = Number(event.target.value);
            choose(Math.abs(asked - current) < step ? stepFrom(current, Math.sign(asked - current)) : asked);
          }}
          onKeyDown={handleKeyDown}
          className="peer pointer-events-none absolute inset-0 size-full appearance-none opacity-0"
        />
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 rounded-xl peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-inset"
        />
      </div>
    </div>
  );
}
